def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'
    if n == 4:
        return 'C'

    my_last, opp_last = history[-1]
    opp_prev = [h[1] for h in history[-5:]]
    my_prev = [h[0] for h in history[-5:]]

    opp_defections = sum(1 for x in opp_prev if x == 'D')
    my_defections = sum(1 for x in my_prev if x == 'D')

    if n < 10:
        if opp_last == 'D':
            return 'D'
        return 'C'

    total_opp_d = sum(1 for h in history if h[1] == 'D')
    total_my_d = sum(1 for h in history if h[0] == 'D')

    opp_recent_d = sum(1 for h in history[-10:] if h[1] == 'D')
    my_recent_d = sum(1 for h in history[-10:] if h[0] == 'D')

    last_15_opp = [h[1] for h in history[-15:]]
    opp_alt = True
    for i in range(1, len(last_15_opp)):
        if last_15_opp[i] == last_15_opp[i-1]:
            opp_alt = False
            break

    if opp_alt and len(last_15_opp) >= 6:
        return 'D' if opp_last == 'C' else 'C'

    if opp_recent_d == 0 and my_recent_d == 0:
        return 'C'

    if opp_recent_d >= 8:
        return 'D'

    if opp_last == 'D' and my_last == 'C':
        if total_opp_d > n * 0.6:
            return 'D'
        return 'D'

    if opp_last == 'D' and my_last == 'D':
        if opp_recent_d >= 4:
            return 'D'
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    if opp_last == 'C' and my_last == 'D':
        if opp_recent_d >= 3:
            return 'D' if rng.random() < 0.5 else 'C'
        return 'C'

    if opp_recent_d >= 3:
        return 'D' if rng.random() < 0.6 else 'C'

    return 'C'

